def decide(recipient_reputation, round_num, my_history):
    # Base threshold depends on round number (more generous early)
    if round_num < 5:
        base_threshold = 0.2
    else:
        base_threshold = 0.6

    # Personal history: if we donated in at least 3 of the last 5 rounds, lower threshold
    recent_my_donations = 0
    if len(my_history) >= 5:
        recent_my_donations = sum(1 for (_, a) in my_history[-5:] if a == 'donate')
    else:
        recent_my_donations = sum(1 for (_, a) in my_history if a == 'donate')

    if recent_my_donations >= 3:
        base_threshold -= 0.3

    return recipient_reputation > max(0.0, base_threshold)

def evaluate(current_reputation, observation, my_history, round_num):
    # Update reputation using an asymmetric step that also depends on the current reputation.
    # Reward donations generously (+0.3) but punish no-donations mildly (-0.1).
    # The actual change is scaled by (1 - |current_reputation|) to avoid overshoot.
    if observation['action'] == 'donate':
        delta = 0.3 * (1 - abs(current_reputation))
    else:
        delta = -0.1 * (1 - abs(current_reputation))
    new_rep = current_reputation + delta
    # Clamp to [-1.0, 1.0] to respect the valid range
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Compute own donation rate (excluding current round) to influence threshold.
    # A higher own donation rate makes us more willing to donate (lower threshold).
    if len(my_history) > 0:
        own_donations = sum(1 for h in my_history if h['action'] == 'donate')
        own_rate = own_donations / len(my_history)
    else:
        own_rate = 0.5  # default before any history
    # Threshold is dynamically adjusted: more cooperative agents accept lower reputations.
    # Range: if own_rate=0 → threshold=0.7; if own_rate=1 → threshold=0.5.
    threshold = 0.7 - 0.2 * own_rate
    return recipient_reputation >= threshold
